export const myMastery = async (
  courseId: CourseId,
  options?: Parameters<typeof orvalMutator>[1],
): Promise<LearnerMastery> => {
  return orvalMutator<LearnerMastery>(
    getMyMasteryUrl(courseId),
    {
      ...options,
      method: 'GET',
    },
    LearnerMastery,
  )
}

